mapper.select:
SELECT id, title, cover_url, video_url, latitude, longitude, location_name, content_md, status, published_at, created_at, updated_at, (SELECT COUNT(*) FROM work_likes wl WHERE wl.work_id = works.id) AS like_count, (SELECT COUNT(*) FROM work_favorites wf WHERE wf.work_id = works.id) AS favorite_count, AS distance FROM works
status = 'published' AND latitude IS NOT NULL AND longitude IS NOT NULL AND latitude BETWEEN #{minLat} AND #{maxLat} AND longitude BETWEEN #{minLng} AND #{maxLng} AND <= #{radiusKm}
ORDER BY distance ASC, id DESC

mapper.update:
UPDATE works
title = #{title}, cover_url = #{coverUrl}, video_url = #{videoUrl}, content_md = #{contentMd}, status = #{status}, published_at = #{publishedAt}, updated_at = #{updatedAt}
WHERE id = #{id}

